import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { toast } from 'sonner';

import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@/components/ui/select';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter,
} from '@/components/ui/dialog';
import {
  ArrowLeft, Plus, Save, Trash2, Loader2, MessageCircle, Star, ShieldAlert,
  Search, CheckCheck, Sparkles, AlertCircle, Copy
} from 'lucide-react';
import { formatApiError } from '@/lib/apiErrors';
import { handleSafeBack } from '@/lib/navigation';

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL || (typeof window !== 'undefined' && window.location.hostname.includes('leamss.com') ? 'https://api.leamss.com' : 'http://localhost:8001');
const API = `${BACKEND_URL}/api`;

const CATEGORIES = [
  'Introduction',
  'Assessment',
  'Follow-up',
  'Documentation',
  'Meeting',
  'Closing',
  'Update',
  'Urgent',
  'General'
];

const CATEGORY_COLORS = {
  Introduction: 'bg-emerald-100 text-emerald-800 border-emerald-200',
  Assessment: 'bg-blue-100 text-blue-800 border-blue-200',
  'Follow-up': 'bg-amber-100 text-amber-800 border-amber-200',
  Documentation: 'bg-purple-100 text-purple-800 border-purple-200',
  Meeting: 'bg-indigo-100 text-indigo-800 border-indigo-200',
  Closing: 'bg-teal-100 text-teal-800 border-teal-200',
  Update: 'bg-sky-100 text-sky-800 border-sky-200',
  Urgent: 'bg-rose-100 text-rose-800 border-rose-200',
  General: 'bg-slate-100 text-slate-800 border-slate-200',
};

const BLANK_TEMPLATE = {
  title: '',
  category: 'General',
  text: '',
  is_default: false,
};

export default function WhatsAppTemplatesManager({ isEmbedded = false, onBackToHub, onTemplateSaved }) {
  const navigate = useNavigate();
  const token = localStorage.getItem('token');
  const headers = useMemo(() => ({ Authorization: `Bearer ${token}` }), [token]);

  const user = useMemo(() => {
    try { return JSON.parse(localStorage.getItem('user') || '{}'); } catch { return {}; }
  }, []);
  const isAdmin = ['admin', 'admin_owner', 'super_admin'].includes(user.role) ||
                  ['admin', 'admin_owner', 'super_admin'].includes(user.rbac_role) ||
                  Boolean(user.is_admin);

  const [templates, setTemplates] = useState([]);
  const [placeholders, setPlaceholders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedId, setSelectedId] = useState(null);
  const [form, setForm] = useState(BLANK_TEMPLATE);
  const [search, setSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [saving, setSaving] = useState(false);
  const [templateToDelete, setTemplateToDelete] = useState(null);
  const [deleting, setDeleting] = useState(false);
  const textareaRef = useRef(null);

  const loadData = useCallback(async () => {
    setLoading(true);
    try {
      const [tRes, phRes] = await Promise.all([
        axios.get(`${API}/whatsapp-templates`, { headers }),
        axios.get(`${API}/whatsapp-templates/placeholders`, { headers }).catch(() => ({ data: { placeholders: [] } })),
      ]);
      const list = tRes.data.templates || [];
      setTemplates(list);
      setPlaceholders(phRes.data.placeholders || []);
      if (list.length > 0 && !selectedId) {
        setSelectedId(list[0].id);
        setForm({
          title: list[0].title || list[0].name || '',
          category: list[0].category || 'General',
          text: list[0].text || list[0].body || '',
          is_default: Boolean(list[0].is_default),
        });
      }
    } catch (e) {
      toast.error(formatApiError(e, 'Could not load WhatsApp templates'));
    } finally {
      setLoading(false);
    }
  }, [headers, selectedId]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const selectTemplate = (t) => {
    setSelectedId(t.id);
    setForm({
      title: t.title || t.name || '',
      category: t.category || 'General',
      text: t.text || t.body || '',
      is_default: Boolean(t.is_default),
    });
  };

  const startNewTemplate = () => {
    setSelectedId(null);
    setForm(BLANK_TEMPLATE);
    if (textareaRef.current) textareaRef.current.focus();
  };

  const insertPlaceholder = (tag) => {
    const el = textareaRef.current;
    if (!el) {
      setForm(prev => ({ ...prev, text: prev.text + ` ${tag} ` }));
      return;
    }
    const start = el.selectionStart || 0;
    const end = el.selectionEnd || 0;
    const newText = form.text.substring(0, start) + tag + form.text.substring(end);
    setForm(prev => ({ ...prev, text: newText }));
    setTimeout(() => {
      el.focus();
      el.setSelectionRange(start + tag.length, start + tag.length);
    }, 50);
  };

  const handleSave = async () => {
    if (!form.title.trim()) {
      toast.error('Please enter a template title');
      return;
    }
    if (!form.text.trim()) {
      toast.error('Template message text cannot be empty');
      return;
    }

    setSaving(true);
    try {
      if (selectedId) {
        await axios.put(`${API}/whatsapp-templates/${selectedId}`, form, { headers });
        toast.success('WhatsApp Template updated successfully!');
      } else {
        const res = await axios.post(`${API}/whatsapp-templates`, form, { headers });
        setSelectedId(res.data.id);
        toast.success('WhatsApp Template created successfully!');
      }
      await loadData();
      if (typeof onTemplateSaved === 'function') onTemplateSaved();
    } catch (e) {
      toast.error(formatApiError(e, 'Failed to save WhatsApp template'));
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!templateToDelete) return;
    setDeleting(true);
    try {
      await axios.delete(`${API}/whatsapp-templates/${templateToDelete.id}`, { headers });
      toast.success('Template deleted successfully');
      setTemplateToDelete(null);
      setSelectedId(null);
      setForm(BLANK_TEMPLATE);
      await loadData();
      if (typeof onTemplateSaved === 'function') onTemplateSaved();
    } catch (e) {
      toast.error(formatApiError(e, 'Failed to delete template'));
    } finally {
      setDeleting(false);
    }
  };

  const filteredTemplates = templates.filter(t => {
    const titleStr = t.title || t.name || '';
    const textStr = t.text || t.body || '';
    const matchesSearch = !search ||
      titleStr.toLowerCase().includes(search.toLowerCase()) ||
      textStr.toLowerCase().includes(search.toLowerCase());
    const matchesCat = selectedCategory === 'All' || t.category === selectedCategory;
    return matchesSearch && matchesCat;
  });

  const previewSampleText = useMemo(() => {
    if (!form.text) return 'Select or type a template to see preview...';
    return form.text
      .replace(/{client_name}/g, 'Rahul')
      .replace(/{full_name}/g, 'Rahul Sharma')
      .replace(/{consultant_name}/g, user?.name || 'Pooja Gha')
      .replace(/{country}/g, 'Canada')
      .replace(/{service}/g, 'Express Entry Consultation')
      .replace(/{phone}/g, '+91 9423391355');
  }, [form.text, user?.name]);

  if (!isAdmin) {
    return (
      <div className="min-h-[500px] flex items-center justify-center p-6 bg-slate-50">
        <Card className="max-w-md w-full p-6 text-center space-y-4 shadow-lg border-rose-200 bg-white">
          <div className="w-14 h-14 bg-rose-100 text-rose-600 rounded-full flex items-center justify-center mx-auto">
            <ShieldAlert className="w-7 h-7" />
          </div>
          <div>
            <h2 className="text-lg font-bold text-slate-900">Admin-Only Section</h2>
            <p className="text-xs text-slate-500 mt-2 leading-relaxed">
              WhatsApp Template Management is restricted to Administrators only.
              Sales Persons cannot create, modify, or delete templates.
            </p>
            <p className="text-xs text-emerald-800 bg-emerald-50 border border-emerald-200 p-2.5 rounded-lg mt-3 font-medium">
              💡 Sales Consultants can select and use all approved Admin templates directly when messaging clients in CRM.
            </p>
          </div>
          {onBackToHub ? (
            <Button onClick={onBackToHub} className="bg-emerald-700 hover:bg-emerald-800 text-white text-xs">
              Back to Dashboard
            </Button>
          ) : (
            <Button onClick={() => handleSafeBack(navigate, '/sales/my-crm')} className="bg-emerald-700 hover:bg-emerald-800 text-white text-xs">
              Go to My CRM
            </Button>
          )}
        </Card>
      </div>
    );
  }

  return (
    <div className="p-4 sm:p-6 space-y-5 max-w-7xl mx-auto">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pb-3 border-b border-slate-200">
        <div className="flex items-center gap-3">
          {onBackToHub ? (
            <Button variant="ghost" size="sm" onClick={onBackToHub} className="h-8 px-2 text-slate-500 hover:text-slate-900">
              <ArrowLeft className="w-4 h-4 mr-1" /> Back
            </Button>
          ) : (
            <Button variant="ghost" size="sm" onClick={() => handleSafeBack(navigate, '/sales/my-crm')} className="h-8 px-2 text-slate-500 hover:text-slate-900">
              <ArrowLeft className="w-4 h-4 mr-1" /> Back to CRM
            </Button>
          )}
          <div>
            <h1 className="text-xl font-bold text-slate-900 flex items-center gap-2">
              <MessageCircle className="w-5 h-5 text-emerald-600" /> WhatsApp Templates Management
            </h1>
            <p className="text-xs text-slate-500 mt-0.5">
              Standardized, approved WhatsApp templates for sales consultants with 1-click personalization tags.
            </p>
          </div>
        </div>

        <Button
          size="sm"
          onClick={startNewTemplate}
          className="bg-emerald-600 hover:bg-emerald-700 text-white text-xs gap-1.5 shadow-sm font-semibold h-8"
        >
          <Plus className="w-3.5 h-3.5" /> Create New Template
        </Button>
      </div>

      {/* Main Grid: Left List + Right Editor */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-5">
        
        {/* Left List: 5 Cols */}
        <div className="lg:col-span-5 space-y-3">
          <Card className="p-3 bg-white border-slate-200 shadow-sm space-y-2.5">
            {/* Search */}
            <div className="relative">
              <Search className="w-3.5 h-3.5 absolute left-2.5 top-2.5 text-slate-400" />
              <Input
                placeholder="Search templates..."
                value={search}
                onChange={e => setSearch(e.target.value)}
                className="pl-8 h-8 text-xs bg-slate-50 border-slate-200 focus:bg-white"
              />
            </div>

            {/* Category Pills */}
            <div className="flex flex-wrap gap-1 pt-1 pb-1">
              {['All', ...CATEGORIES].map(cat => (
                <button
                  key={cat}
                  onClick={() => setSelectedCategory(cat)}
                  className={`px-2 py-0.5 rounded-full text-[10px] font-semibold transition-all ${
                    selectedCategory === cat
                      ? 'bg-emerald-700 text-white shadow-xs'
                      : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </Card>

          {/* Templates List */}
          <div className="space-y-2 max-h-[620px] overflow-y-auto pr-1">
            {loading ? (
              <div className="p-8 text-center text-xs text-slate-400 space-y-2">
                <Loader2 className="w-5 h-5 animate-spin mx-auto text-emerald-600" />
                <p>Loading WhatsApp templates...</p>
              </div>
            ) : filteredTemplates.length === 0 ? (
              <div className="p-8 text-center text-xs text-slate-400 bg-white border border-dashed border-slate-200 rounded-xl">
                <MessageCircle className="w-8 h-8 mx-auto text-slate-300 mb-2" />
                <p className="font-semibold text-slate-600">No templates found</p>
                <p className="text-[11px] text-slate-400 mt-1">Try another search or create a new template.</p>
              </div>
            ) : (
              filteredTemplates.map(t => {
                const isSelected = selectedId === t.id;
                const catClass = CATEGORY_COLORS[t.category] || CATEGORY_COLORS.General;
                const titleStr = t.title || t.name || 'Untitled';
                const textStr = t.text || t.body || '';
                return (
                  <div
                    key={t.id}
                    onClick={() => selectTemplate(t)}
                    className={`p-3 rounded-xl border text-left cursor-pointer transition-all relative group ${
                      isSelected
                        ? 'bg-emerald-50/70 border-emerald-400 shadow-sm ring-1 ring-emerald-300'
                        : 'bg-white border-slate-200 hover:border-slate-300 hover:bg-slate-50/50'
                    }`}
                  >
                    <div className="flex items-start justify-between gap-2">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-1.5 flex-wrap">
                          <span className="font-bold text-xs text-slate-900 truncate">{titleStr}</span>
                          {t.is_default && (
                            <Badge className="bg-amber-100 text-amber-800 border-amber-200 text-[9px] px-1 py-0 font-bold gap-0.5">
                              <Star className="w-2.5 h-2.5 fill-amber-500 text-amber-500" /> Default
                            </Badge>
                          )}
                        </div>
                        <span className={`inline-block mt-1 px-1.5 py-0.2 rounded border text-[9px] font-semibold ${catClass}`}>
                          {t.category || 'General'}
                        </span>
                        <p className="text-[11px] text-slate-600 line-clamp-2 mt-1 leading-snug">
                          {textStr}
                        </p>
                      </div>

                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={(e) => {
                          e.stopPropagation();
                          setTemplateToDelete(t);
                        }}
                        className="h-7 w-7 text-slate-400 hover:text-rose-600 hover:bg-rose-50 opacity-0 group-hover:opacity-100 transition-opacity flex-shrink-0"
                        title="Delete template"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </Button>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        {/* Right Editor + Preview: 7 Cols */}
        <div className="lg:col-span-7 space-y-4">
          <Card className="p-4 sm:p-5 bg-white border-slate-200 shadow-sm space-y-4">
            <div className="flex items-center justify-between pb-3 border-b border-slate-100">
              <h2 className="text-sm font-bold text-slate-900 flex items-center gap-1.5">
                <Sparkles className="w-4 h-4 text-emerald-600" />
                {selectedId ? 'Edit WhatsApp Template' : 'Create New WhatsApp Template'}
              </h2>
              {selectedId && (
                <span className="text-[10px] text-slate-400 font-mono">ID: {selectedId}</span>
              )}
            </div>

            {/* Title & Category Row */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              <div className="sm:col-span-2 space-y-1">
                <Label className="text-[11px] font-semibold text-slate-700">Template Title</Label>
                <Input
                  placeholder="e.g. 🌟 Welcome & Profile Introduction"
                  value={form.title}
                  onChange={e => setForm(f => ({ ...f, title: e.target.value }))}
                  className="h-8 text-xs bg-slate-50 border-slate-200 focus:bg-white"
                />
              </div>

              <div className="space-y-1">
                <Label className="text-[11px] font-semibold text-slate-700">Category</Label>
                <Select
                  value={form.category}
                  onValueChange={val => setForm(f => ({ ...f, category: val }))}
                >
                  <SelectTrigger className="h-8 text-xs bg-slate-50 border-slate-200">
                    <SelectValue placeholder="Select Category" />
                  </SelectTrigger>
                  <SelectContent className="z-[99999] bg-white border border-slate-200">
                    {CATEGORIES.map(c => (
                      <SelectItem key={c} value={c} className="text-xs">
                        {c}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            {/* Placeholders Insert Chips */}
            <div className="space-y-1.5 bg-slate-50 p-2.5 rounded-lg border border-slate-200">
              <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wider block">
                Click to Insert Auto-Personalization Tags:
              </span>
              <div className="flex flex-wrap gap-1.5">
                {[
                  { tag: '{client_name}', label: '{client_name}', desc: "Client's first name" },
                  { tag: '{full_name}', label: '{full_name}', desc: "Client's full name" },
                  { tag: '{consultant_name}', label: '{consultant_name}', desc: "Consultant / Sales rep" },
                  { tag: '{country}', label: '{country}', desc: "Target country" },
                  { tag: '{service}', label: '{service}', desc: "Consulting program" },
                  { tag: '{phone}', label: '{phone}', desc: "Phone number" },
                ].map(p => (
                  <button
                    key={p.tag}
                    type="button"
                    onClick={() => insertPlaceholder(p.tag)}
                    className="px-2 py-0.5 rounded bg-white hover:bg-emerald-50 text-slate-700 hover:text-emerald-700 border border-slate-200 hover:border-emerald-300 text-[10px] font-mono transition-colors shadow-2xs"
                    title={p.desc}
                  >
                    + {p.label}
                  </button>
                ))}
              </div>
            </div>

            {/* Textarea */}
            <div className="space-y-1">
              <div className="flex items-center justify-between">
                <Label className="text-[11px] font-semibold text-slate-700">Message Content</Label>
                <span className={`text-[10px] ${form.text.length > 800 ? 'text-amber-600 font-bold' : 'text-slate-400'}`}>
                  {form.text.length} characters (ideal: under 600)
                </span>
              </div>
              <Textarea
                ref={textareaRef}
                rows={6}
                placeholder="Type WhatsApp message here. Use merge tags like {client_name} and {consultant_name} to auto-personalize for each lead..."
                value={form.text}
                onChange={e => setForm(f => ({ ...f, text: e.target.value }))}
                className="text-xs font-sans leading-relaxed resize-y bg-slate-50 border-slate-200 focus:bg-white"
              />
            </div>

            {/* Default toggle */}
            <div className="flex items-center justify-between pt-1">
              <div className="flex items-center gap-2">
                <Switch
                  checked={form.is_default}
                  onCheckedChange={checked => setForm(f => ({ ...f, is_default: checked }))}
                  id="wa-default-toggle"
                />
                <Label htmlFor="wa-default-toggle" className="text-xs text-slate-700 cursor-pointer">
                  Set as default template for this category
                </Label>
              </div>

              <Button
                size="sm"
                onClick={handleSave}
                disabled={saving}
                className="bg-emerald-600 hover:bg-emerald-700 text-white text-xs gap-1.5 font-bold shadow-sm h-8 px-4"
              >
                {saving ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Save className="w-3.5 h-3.5" />}
                {selectedId ? 'Save Changes' : 'Create Template'}
              </Button>
            </div>
          </Card>

          {/* Live Mobile WhatsApp Preview Card */}
          <Card className="p-4 bg-slate-50 border-slate-200 shadow-sm space-y-2.5">
            <div className="flex items-center justify-between">
              <span className="text-xs font-bold text-slate-700 flex items-center gap-1.5">
                <MessageCircle className="w-3.5 h-3.5 text-emerald-600" /> Live WhatsApp Chat Preview (Sample Data)
              </span>
              <span className="text-[10px] text-slate-400">Shows how the client sees this message</span>
            </div>

            {/* Phone Screen Mock */}
            <div className="max-w-md mx-auto bg-[#e5ddd5] rounded-xl overflow-hidden border border-slate-300 shadow-inner">
              {/* WhatsApp Chat Header */}
              <div className="bg-[#075e54] text-white px-3 py-2 flex items-center gap-2 text-xs">
                <div className="w-7 h-7 rounded-full bg-emerald-800 border border-emerald-400 flex items-center justify-center font-bold text-[10px]">
                  L
                </div>
                <div>
                  <p className="font-bold leading-tight">LEAMSS Immigration</p>
                  <p className="text-[9px] text-emerald-200">Online</p>
                </div>
              </div>

              {/* Chat Bubble Area */}
              <div className="p-4 min-h-[140px] flex flex-col justify-end">
                <div className="bg-[#dcf8c6] text-slate-900 rounded-lg rounded-tr-none p-3 max-w-[90%] ml-auto shadow text-xs whitespace-pre-wrap leading-relaxed relative border border-emerald-200/50">
                  <p className="text-[11px] text-slate-800">{previewSampleText}</p>
                  <div className="flex items-center justify-end gap-1 mt-1.5 text-[9px] text-slate-500">
                    <span>12:45 PM</span>
                    <CheckCheck className="w-3 h-3 text-sky-600" />
                  </div>
                </div>
              </div>
            </div>
          </Card>

        </div>
      </div>

      {/* Delete Confirmation Modal */}
      <Dialog open={Boolean(templateToDelete)} onOpenChange={() => setTemplateToDelete(null)}>
        <DialogContent className="max-w-sm bg-white border border-slate-200 z-[99999]">
          <DialogHeader>
            <DialogTitle className="text-sm font-bold text-rose-700 flex items-center gap-1.5">
              <AlertCircle className="w-4 h-4 text-rose-600" /> Delete WhatsApp Template?
            </DialogTitle>
            <DialogDescription className="text-xs text-slate-600">
              Are you sure you want to delete <strong>{templateToDelete?.title || templateToDelete?.name}</strong>? Sales persons will no longer be able to select this template.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter className="flex gap-2 justify-end pt-2">
            <Button size="sm" variant="outline" onClick={() => setTemplateToDelete(null)} className="text-xs">
              Cancel
            </Button>
            <Button size="sm" onClick={handleDelete} disabled={deleting} className="bg-rose-600 hover:bg-rose-700 text-white text-xs font-semibold">
              {deleting ? <Loader2 className="w-3.5 h-3.5 animate-spin mr-1" /> : <Trash2 className="w-3.5 h-3.5 mr-1" />}
              Delete
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
