import React, { useRef, useEffect, useState, useCallback } from 'react';
import {
  Bold,
  Italic,
  Underline,
  List,
  ListOrdered,
  AlignLeft,
  AlignCenter,
  AlignRight,
  Undo2,
  Redo2,
  RemoveFormatting,
  Heading1,
  Heading2,
  Heading3,
  Type,
  Code,
  RotateCcw,
  Sparkles,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import './agreement-doc.css';

/**
 * RichTextDocumentEditor
 * A visual WYSIWYG document editor that displays and edits agreement content in
 * formatted text mode (Word / Google Docs style), with no raw code or HTML tags exposed.
 *
 * Props:
 * - value: HTML string
 * - onChange: (html: string) => void
 * - editable: boolean (default true)
 * - minHeight: string (default '420px')
 * - maxHeight: string (default '600px')
 * - onReset: optional () => void callback to reset to original
 * - placeholders: optional string[] of available variable names
 * - allowCodeToggle: optional boolean to allow developers to view raw code if needed (default false)
 * - className: optional string
 */
export default function RichTextDocumentEditor({
  value = '',
  onChange,
  editable = true,
  minHeight = '420px',
  maxHeight = '620px',
  onReset,
  placeholders = [],
  allowCodeToggle = true,
  className = '',
}) {
  const editorRef = useRef(null);
  const isFocusedRef = useRef(false);
  const [viewMode, setViewMode] = useState('visual'); // 'visual' | 'code'

  // Initialize and synchronize innerHTML when value changes externally (not during active typing)
  useEffect(() => {
    if (editorRef.current && !isFocusedRef.current) {
      if (editorRef.current.innerHTML !== value) {
        editorRef.current.innerHTML = value || '';
      }
    }
  }, [value]);

  const handleInput = useCallback(() => {
    if (!editorRef.current) return;
    const newHtml = editorRef.current.innerHTML;
    if (onChange) {
      onChange(newHtml);
    }
  }, [onChange]);

  // Execute standard formatting commands while preventing focus loss
  const execCmd = (command, val = null) => {
    if (!editable) return;
    if (editorRef.current) {
      editorRef.current.focus();
    }
    try {
      document.execCommand(command, false, val);
    } catch (err) {
      console.warn('execCommand failed:', err);
    }
    handleInput();
  };

  const insertPlaceholder = (ph) => {
    if (!editable) return;
    if (editorRef.current) {
      editorRef.current.focus();
    }
    const token = `{{${ph}}}`;
    try {
      document.execCommand('insertText', false, token);
    } catch {
      if (window.getSelection) {
        const sel = window.getSelection();
        if (sel.getRangeAt && sel.rangeCount) {
          const range = sel.getRangeAt(0);
          range.deleteContents();
          range.insertNode(document.createTextNode(token));
        }
      }
    }
    handleInput();
  };

  return (
    <div className={`rich-text-doc-editor border border-slate-200 rounded-lg shadow-sm bg-white overflow-hidden ${className}`}>
      {/* Top Toolbar */}
      {editable && (
        <div className="bg-slate-50 border-b border-slate-200 px-3 py-1.5 flex flex-wrap items-center justify-between gap-1 text-slate-700 select-none">
          {/* Formatting Actions */}
          <div className="flex flex-wrap items-center gap-0.5">
            {/* Undo / Redo */}
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => execCmd('undo')}
              title="Undo (Ctrl+Z)"
              className="p-1.5 rounded hover:bg-slate-200 text-slate-600 transition"
            >
              <Undo2 className="h-4 w-4" />
            </button>
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => execCmd('redo')}
              title="Redo (Ctrl+Y)"
              className="p-1.5 rounded hover:bg-slate-200 text-slate-600 transition"
            >
              <Redo2 className="h-4 w-4" />
            </button>

            <span className="w-px h-5 bg-slate-300 mx-1" />

            {/* Paragraph / Headings */}
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => execCmd('formatBlock', '<p>')}
              title="Normal Paragraph"
              className="px-2 py-1 text-xs font-semibold rounded hover:bg-slate-200 text-slate-700 flex items-center gap-1 transition"
            >
              <Type className="h-3.5 w-3.5" /> Normal
            </button>
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => execCmd('formatBlock', '<h1>')}
              title="Heading 1"
              className="p-1.5 rounded hover:bg-slate-200 text-slate-700 transition"
            >
              <Heading1 className="h-4 w-4" />
            </button>
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => execCmd('formatBlock', '<h2>')}
              title="Heading 2"
              className="p-1.5 rounded hover:bg-slate-200 text-slate-700 transition"
            >
              <Heading2 className="h-4 w-4" />
            </button>
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => execCmd('formatBlock', '<h3>')}
              title="Heading 3"
              className="p-1.5 rounded hover:bg-slate-200 text-slate-700 transition"
            >
              <Heading3 className="h-4 w-4" />
            </button>

            <span className="w-px h-5 bg-slate-300 mx-1" />

            {/* Inline styles: Bold, Italic, Underline */}
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => execCmd('bold')}
              title="Bold (Ctrl+B)"
              className="p-1.5 rounded hover:bg-slate-200 text-slate-800 font-bold transition"
            >
              <Bold className="h-4 w-4" />
            </button>
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => execCmd('italic')}
              title="Italic (Ctrl+I)"
              className="p-1.5 rounded hover:bg-slate-200 text-slate-800 italic transition"
            >
              <Italic className="h-4 w-4" />
            </button>
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => execCmd('underline')}
              title="Underline (Ctrl+U)"
              className="p-1.5 rounded hover:bg-slate-200 text-slate-800 underline transition"
            >
              <Underline className="h-4 w-4" />
            </button>

            <span className="w-px h-5 bg-slate-300 mx-1" />

            {/* Lists */}
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => execCmd('insertUnorderedList')}
              title="Bulleted List"
              className="p-1.5 rounded hover:bg-slate-200 text-slate-700 transition"
            >
              <List className="h-4 w-4" />
            </button>
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => execCmd('insertOrderedList')}
              title="Numbered List"
              className="p-1.5 rounded hover:bg-slate-200 text-slate-700 transition"
            >
              <ListOrdered className="h-4 w-4" />
            </button>

            <span className="w-px h-5 bg-slate-300 mx-1" />

            {/* Alignment */}
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => execCmd('justifyLeft')}
              title="Align Left"
              className="p-1.5 rounded hover:bg-slate-200 text-slate-700 transition"
            >
              <AlignLeft className="h-4 w-4" />
            </button>
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => execCmd('justifyCenter')}
              title="Align Center"
              className="p-1.5 rounded hover:bg-slate-200 text-slate-700 transition"
            >
              <AlignCenter className="h-4 w-4" />
            </button>
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => execCmd('justifyRight')}
              title="Align Right"
              className="p-1.5 rounded hover:bg-slate-200 text-slate-700 transition"
            >
              <AlignRight className="h-4 w-4" />
            </button>

            <span className="w-px h-5 bg-slate-300 mx-1" />

            {/* Clear Formatting */}
            <button
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => execCmd('removeFormat')}
              title="Clear Formatting"
              className="p-1.5 rounded hover:bg-slate-200 text-slate-600 transition"
            >
              <RemoveFormatting className="h-4 w-4" />
            </button>
          </div>

          {/* Right utility buttons: Reset & View Mode */}
          <div className="flex items-center gap-1.5">
            {onReset && (
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={onReset}
                title="Discard manual text edits and restore from template"
                className="h-7 text-xs text-amber-700 hover:bg-amber-100 flex items-center gap-1"
              >
                <RotateCcw className="h-3.5 w-3.5" /> Reset to Template
              </Button>
            )}

            {allowCodeToggle && (
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={() => setViewMode(viewMode === 'visual' ? 'code' : 'visual')}
                title="Toggle Code Mode"
                className="h-7 text-xs text-slate-600 hover:bg-slate-200 flex items-center gap-1"
              >
                <Code className="h-3.5 w-3.5" />
                {viewMode === 'visual' ? 'HTML Code' : 'Text Editor'}
              </Button>
            )}
          </div>
        </div>
      )}

      {/* Placeholders bar if available */}
      {editable && placeholders && placeholders.length > 0 && (
        <div className="bg-teal-50/70 border-b border-teal-100 px-3 py-1.5 flex items-center gap-1.5 flex-wrap text-xs text-teal-900">
          <span className="font-semibold flex items-center gap-1">
            <Sparkles className="h-3.5 w-3.5 text-teal-600" /> Insert Placeholder:
          </span>
          <div className="flex flex-wrap gap-1">
            {placeholders.slice(0, 8).map((ph) => (
              <button
                key={ph}
                type="button"
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => insertPlaceholder(ph)}
                className="bg-white border border-teal-200 hover:bg-teal-100 text-teal-800 text-[11px] px-1.5 py-0.5 rounded shadow-2xs font-mono transition"
                title={`Insert {{${ph}}} at current cursor`}
              >
                + {ph}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Main Document Content Area */}
      {viewMode === 'code' ? (
        <div className="p-2 bg-slate-900">
          <textarea
            value={value}
            onChange={(e) => onChange && onChange(e.target.value)}
            rows={18}
            className="w-full font-mono text-xs p-3 border-0 focus:outline-none bg-slate-900 text-slate-100 rounded"
            placeholder="Agreement HTML source"
          />
        </div>
      ) : (
        <div
          className="agreement-doc-wrap overflow-y-auto bg-slate-100 p-4"
          style={{ maxHeight, minHeight }}
        >
          <div
            ref={editorRef}
            contentEditable={editable}
            suppressContentEditableWarning={true}
            onInput={handleInput}
            onBlur={() => {
              isFocusedRef.current = false;
              handleInput();
            }}
            onFocus={() => {
              isFocusedRef.current = true;
            }}
            className="agreement-doc outline-none cursor-text focus:ring-2 focus:ring-teal-500/30 transition-shadow"
            style={{
              minHeight: '380px',
              backgroundColor: '#ffffff',
            }}
            data-testid="rich-text-document-editor"
          />
        </div>
      )}

      {/* Footer Status Bar */}
      <div className="bg-slate-50 border-t border-slate-200 px-3 py-1.5 text-[11px] text-slate-500 flex items-center justify-between">
        <span className="flex items-center gap-1.5">
          <span className="inline-block w-2 h-2 rounded-full bg-emerald-500" />
          {editable ? (
            <span><strong>Formatted Document Editor:</strong> Click anywhere on the text to edit directly.</span>
          ) : (
            <span><strong>Formatted Preview:</strong> Read-only view.</span>
          )}
        </span>
        <span className="text-slate-400">Word-Processor Text Format</span>
      </div>
    </div>
  );
}
