import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { toast } from 'sonner';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Target, Award, ArrowLeft, HelpCircle, CheckCircle2, AlertCircle,
  BarChart2, Calendar, FileText
} from 'lucide-react';

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL || (typeof window !== 'undefined' && window.location.hostname.includes('leamss.com') ? 'https://api.leamss.com' : 'http://localhost:8001');
const API = `${BACKEND_URL}/api`;

export default function MyScore() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [scorecard, setScorecard] = useState(null);
  const [queryModalKpi, setQueryModalKpi] = useState(null);
  const [queryReason, setQueryReason] = useState('');
  const [submittingQuery, setSubmittingQuery] = useState(false);

  const fetchScore = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('token');
      const res = await axios.get(`${API}/me/score`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setScorecard(res.data.data);
    } catch (err) {
      toast.error(err?.response?.data?.detail || 'Failed to fetch score');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchScore();
  }, []);

  const handleScoreQuery = async (e) => {
    e.preventDefault();
    if (!queryReason || queryReason.length < 10) {
      toast.error('Please provide at least 10 characters explaining your query.');
      return;
    }

    try {
      setSubmittingQuery(true);
      const token = localStorage.getItem('token');
      await axios.post(
        `${API}/me/score/${scorecard.scorecard_id}/query`,
        {
          kpi_key: queryModalKpi?.key || null,
          reason: queryReason,
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      toast.success('Scorecard query submitted for manager/council review.');
      setQueryModalKpi(null);
      setQueryReason('');
    } catch (err) {
      toast.error(err?.response?.data?.detail || 'Failed to submit score query');
    } finally {
      setSubmittingQuery(false);
    }
  };

  const finalScore = scorecard?.final_score || 0;
  const grade = scorecard?.grade || 'In Progress';
  const kpis = scorecard?.kpis || [];

  return (
    <div className="min-h-screen bg-slate-50 p-4 sm:p-6 lg:p-8">
      <div className="max-w-4xl mx-auto space-y-6">

        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div className="flex items-center gap-3">
            <Button
              variant="outline"
              size="icon"
              onClick={() => navigate('/portal/hub')}
              className="h-9 w-9 border-slate-300"
            >
              <ArrowLeft className="h-4 w-4" />
            </Button>
            <div>
              <h1 className="text-2xl font-bold tracking-tight text-slate-900">My Scorecard</h1>
              <p className="text-sm text-slate-500">Performance grading, SLA compliance, and KPI breakdown</p>
            </div>
          </div>
          {scorecard?.month && (
            <Badge variant="outline" className="bg-slate-100 font-mono text-slate-700 py-1 px-3">
              Period: {scorecard.month}
            </Badge>
          )}
        </div>

        {loading ? (
          <div className="p-12 text-center text-slate-400">Loading scorecard...</div>
        ) : !scorecard ? (
          <Card className="p-12 text-center text-slate-500 bg-white">
            <Target className="h-10 w-10 text-slate-300 mx-auto mb-3" />
            <h3 className="text-base font-semibold text-slate-700">No Scorecard Published Yet</h3>
            <p className="text-xs text-slate-400 mt-1">
              Your monthly scorecard is published after attendance and QC checks finalize at month-end.
            </p>
          </Card>
        ) : (
          <>
            {/* Score Summary Banner */}
            <Card className="p-6 bg-gradient-to-br from-indigo-900 to-slate-900 text-white shadow-md rounded-xl">
              <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-6">
                <div>
                  <span className="text-xs font-semibold uppercase tracking-wider text-indigo-300">
                    Monthly Performance Score
                  </span>
                  <div className="flex items-baseline gap-3 mt-1">
                    <span className="text-5xl font-black">{finalScore.toFixed(1)}</span>
                    <span className="text-xl text-indigo-300 font-medium">/ 100</span>
                  </div>
                  <div className="mt-3 flex items-center gap-2">
                    <Badge className="bg-emerald-500/20 text-emerald-300 border border-emerald-500/30">
                      Grade: {grade}
                    </Badge>
                    <Badge variant="outline" className="border-indigo-400 text-indigo-200">
                      Status: {scorecard.status || 'Active'}
                    </Badge>
                  </div>
                </div>

                <div className="flex flex-col gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setQueryModalKpi({ key: 'overall', name: 'Overall Score' })}
                    className="border-indigo-400 text-indigo-100 hover:bg-indigo-800 text-xs"
                  >
                    <HelpCircle className="h-3.5 w-3.5 mr-1" />
                    Query Overall Score
                  </Button>
                </div>
              </div>
            </Card>

            {/* KPI Breakdown */}
            <Card className="bg-white shadow-sm border-slate-200 overflow-hidden">
              <div className="p-4 border-b border-slate-100 flex items-center justify-between">
                <h2 className="text-sm font-semibold text-slate-800 flex items-center gap-2">
                  <BarChart2 className="h-4 w-4 text-indigo-500" />
                  Key Performance Indicators ({kpis.length})
                </h2>
                <span className="text-xs text-slate-400">Weighted scores</span>
              </div>

              <div className="divide-y divide-slate-100">
                {kpis.map((kpi, idx) => (
                  <div key={idx} className="p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-3 hover:bg-slate-50/60 transition">
                    <div className="space-y-1">
                      <div className="flex items-center gap-2">
                        <span className="text-xs font-semibold text-slate-900">{kpi.key || `KPI ${idx+1}`}</span>
                        <Badge variant="outline" className="text-[10px] bg-slate-50">
                          Weight: {kpi.weight}%
                        </Badge>
                      </div>
                      <p className="text-xs text-slate-500">{kpi.description || 'Target performance indicator.'}</p>
                    </div>

                    <div className="flex items-center justify-between sm:justify-end gap-4">
                      <div className="text-right">
                        <div className="text-sm font-bold text-slate-900">
                          {Number(kpi.score || 0).toFixed(1)}%
                        </div>
                        <span className="text-[10px] text-slate-400">
                          Points: {((Number(kpi.score || 0) * Number(kpi.weight || 0)) / 100).toFixed(1)}
                        </span>
                      </div>

                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => setQueryModalKpi({ key: kpi.key, name: kpi.key })}
                        className="text-xs text-slate-400 hover:text-slate-800"
                        title="Query this KPI"
                      >
                        <HelpCircle className="h-3.5 w-3.5 mr-1" />
                        Dispute
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            </Card>
          </>
        )}

        {/* Query Modal */}
        {queryModalKpi && (
          <div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4">
            <Card className="w-full max-w-md bg-white p-6 shadow-xl rounded-xl space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-base font-semibold text-slate-900">Query Scorecard KPI</h3>
                <Button variant="ghost" size="sm" onClick={() => setQueryModalKpi(null)}>✕</Button>
              </div>

              <div className="bg-slate-50 p-3 rounded text-xs space-y-1 font-mono text-slate-600 border border-slate-200">
                <div>Scorecard: {scorecard?.scorecard_id}</div>
                <div>Target: {queryModalKpi.name}</div>
              </div>

              <form onSubmit={handleScoreQuery} className="space-y-4">
                <div>
                  <Label htmlFor="sc-reason" className="text-xs font-medium text-slate-700">Reason for Query</Label>
                  <Textarea
                    id="sc-reason"
                    rows={4}
                    value={queryReason}
                    onChange={(e) => setQueryReason(e.target.value)}
                    placeholder="Explain why this KPI score needs review or recalculation..."
                    className="mt-1 text-xs"
                    required
                  />
                  <p className="text-[11px] text-slate-400 mt-1">
                    Your query will be assigned to your manager and HR for review.
                  </p>
                </div>

                <div className="flex justify-end gap-2 pt-2">
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => setQueryModalKpi(null)}
                  >
                    Cancel
                  </Button>
                  <Button
                    type="submit"
                    size="sm"
                    disabled={submittingQuery}
                    className="bg-indigo-600 hover:bg-indigo-700 text-white"
                  >
                    {submittingQuery ? 'Submitting...' : 'Submit Query'}
                  </Button>
                </div>
              </form>
            </Card>
          </div>
        )}

      </div>
    </div>
  );
}
